class ChatSession:
    def __init__(self, system=''):
        self.system = system
        self.history = []

    def add_user(self, msg):
        self.history.append({'role': 'user', 'content': msg})

    def add_assistant(self, msg):
        self.history.append({'role': 'assistant', 'content': msg})

    def summary(self):
        print(f'턴 수: {len(self.history) // 2}')

session = ChatSession(system='AI 도우미')
session.add_user('안녕')
session.add_assistant('안녕!')
session.add_user('잘 지내?')
session.add_assistant('잘 지내요!')
session.summary()

def stream_text(text, chunk_size=2):
    return [text[i:i+chunk_size] for i in range(0, len(text), chunk_size)]

chunks = stream_text('에이몬AI', 2)
for chunk in chunks:
    print(chunk, end='', flush=True)
print()

