class AIClient:
    def __init__(self, api_key):
        self.api_key = api_key
        self.call_count = 0

    def chat(self, message):
        self.call_count += 1
        return f'[응답] {message}'

    def get_stats(self):
        print(f'호출 횟수: {self.call_count}')

